 19	impl EntityDetailsRepo for ExposedDatabase {
 20	    async fn member(
 21	        &self,
 22	        id: MemberId,
 23	        recent_limit: usize,
 24	    ) -> Result<Option<MemberDetails>, EntityDetailsRepoError> {
 25	        let mut tx = self.pool().begin().await?;
 26	        sqlx::query!("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")
 27	            .execute(&mut *tx)
 28	            .await?;
 29	        let row = sqlx::query!(
 30	            "SELECT parliament_member_id, name, party_id, party_name, latest_membership_from, is_current_commons,
 31	                (SELECT count(*) FROM exposed.declarations d WHERE d.member_id = m.id) AS \"declaration_count!\"
 32	             FROM exposed.members m WHERE parliament_member_id = $1", i32::try_from(id.value()).map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?
 33	        ).fetch_optional(&mut *tx).await?;
 34	        let Some(row) = row else {
 35	            return Ok(None);
 36	        };
 37	        let member = MemberProfile {
 38	            id,
 39	            name: row.name,
 40	            party_id: row.party_id,
 41	            party_name: row.party_name,
 42	            membership_from: row.latest_membership_from,
 43	            is_current_commons: row.is_current_commons,
 44	        };
 45	        let rows = sqlx::query!(
 46	            "WITH recent AS (
 47	                SELECT d.source_declaration_id, d.category_name, d.registration_date
 48	                FROM exposed.declarations d JOIN exposed.members m ON m.id = d.member_id
 49	                WHERE m.parliament_member_id = $1
 50	                ORDER BY d.registration_date DESC NULLS LAST, d.source_declaration_id DESC LIMIT $2
 51	             )
 52	             SELECT d.source_declaration_id, d.category_name, d.registration_date,
 53	                e.id AS \"entry_id?\", e.amount, e.currency, e.payment_type, f.id AS \"funder_id?\", f.funder_name AS \"funder_name?\"
 54	             FROM recent d LEFT JOIN exposed.funding_entries e ON e.source_declaration_id = d.source_declaration_id
 55	             LEFT JOIN exposed.funders f ON f.id = e.funder_id
 56	             ORDER BY d.registration_date DESC NULLS LAST, d.source_declaration_id DESC, e.id",
 57	             i32::try_from(id.value()).map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?,
 58	             i64::try_from(recent_limit).map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?
 59	        ).fetch_all(&mut *tx).await?;
 60	        let mut declarations: Vec<RecentDeclaration> = Vec::new();
 61	        for row in rows {
 62	            if declarations
 63	                .last()
 64	                .is_none_or(|declaration| declaration.source_id != row.source_declaration_id)
 65	            {
 66	                declarations.push(RecentDeclaration {
 67	                    source_id: row.source_declaration_id,
 68	                    category_name: row.category_name,
 69	                    registered_at: row
 70	                        .registration_date
 71	                        .map(|date| {
 72	                            chrono::DateTime::from_timestamp(
 73	                                date.unix_timestamp(),
 74	                                date.nanosecond(),
 75	                            )
 76	                            .ok_or_else(|| {
 77	                                EntityDetailsRepoError::DatabaseError(
 78	                                    "Stored registration date is out of range".into(),
 79	                                )
 80	                            })
 81	                        })
 82	                        .transpose()?,
 83	                    entries: Vec::new(),
 84	                });
 85	            }
 86	            if row.entry_id.is_some() {
 87	                let funder = row
 88	                    .funder_id
 89	                    .zip(row.funder_name)
 90	                    .map(|(id, name)| FunderReference {
 91	                        id: FunderId::new(id),
 92	                        name,
 93	                    });
 94	                if let Some(declaration) = declarations.last_mut() {
 95	                    declaration.entries.push(DeclaredFunding {
 96	                        funder,
 97	                        amount: row.amount,
 98	                        currency: row.currency,
 99	                        payment_type: row.payment_type,
100	                    });
101	                }
102	            }
103	        }
104	        tx.commit().await?;
105	        Ok(Some(MemberDetails {
106	            member,
107	            declarations,
108	            declaration_count: row.declaration_count,
109	            declaration_limit: recent_limit,
110	        }))
111	    }
