113	    async fn funder_funding(
114	        &self,
115	        id: FunderId,
116	    ) -> Result<Option<FunderFunding>, EntityDetailsRepoError> {
117	        let mut tx = self.pool().begin().await?;
118	        sqlx::query!("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")
119	            .execute(&mut *tx)
120	            .await?;
121	        let row = sqlx::query!(
122	            "SELECT funder_name, funder_kind, company_number FROM exposed.funders WHERE id = $1",
123	            id.value()
124	        )
125	        .fetch_optional(&mut *tx)
126	        .await?;
127	        let Some(row) = row else {
128	            return Ok(None);
129	        };
130	        let kind = row
131	            .funder_kind
132	            .as_deref()
133	            .map_or(Ok(FunderKind::NotSpecified), FunderKind::from_str)
134	            .map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?;
135	        let aliases = sqlx::query_scalar!(
136	            "SELECT funder_alias FROM exposed.funder_aliases WHERE funder_id = $1 ORDER BY funder_alias COLLATE \"C\"",
137	            id.value()
138	        )
139	        .fetch_all(&mut *tx)
140	        .await?;
141	        let profile = FunderProfile {
142	            funder: Funder::new(id, row.funder_name, kind),
143	            company_number: row.company_number,
144	            aliases,
145	        };
146	        let rows = sqlx::query!(
147	            "WITH funding AS (
148	                SELECT source_declaration_id, amount, NULLIF(btrim(currency, $2), '') AS currency
149	                FROM exposed.funding_entries WHERE funder_id = $1
150	             )
151	             SELECT m.parliament_member_id, m.name, m.party_id, m.party_name, m.latest_membership_from, m.is_current_commons,
152	                e.currency,
153	                CASE WHEN e.currency IS NOT NULL THEN sum(e.amount) END AS known_total,
154	                count(*) AS \"entry_count!\", count(*) FILTER (WHERE e.amount IS NULL) AS \"unknown_amount_count!\"
155	             FROM funding e JOIN exposed.declarations d ON d.source_declaration_id = e.source_declaration_id
156	             JOIN exposed.members m ON m.id = d.member_id
157	             GROUP BY m.id, e.currency
158	             ORDER BY m.parliament_member_id, currency NULLS LAST", id.value(), CURRENCY_WHITESPACE
159	        ).fetch_all(&mut *tx).await?;
160	        let allocations = rows
161	            .into_iter()
162	            .map(|row| {
163	                let id = row
164	                    .parliament_member_id
165	                    .to_string()
166	                    .parse::<MemberId>()
167	                    .map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?;
168	                Ok(RecipientAllocation {
169	                    member: MemberProfile {
170	                        id,
171	                        name: row.name,
172	                        party_id: row.party_id,
173	                        party_name: row.party_name,
174	                        membership_from: row.latest_membership_from,
175	                        is_current_commons: row.is_current_commons,
176	                    },
177	                    currency: row.currency,
178	                    known_total: row.known_total,
179	                    entry_count: row.entry_count,
180	                    unknown_amount_count: row.unknown_amount_count,
181	                })
182	            })
183	            .collect::<Result<Vec<_>, EntityDetailsRepoError>>()?;
184	        tx.commit().await?;
185	        Ok(Some(FunderFunding {
186	            profile,
187	            allocations,
188	        }))
189	    }
190	}
