   116	    ) -> Result<Option<FunderFunding>, EntityDetailsRepoError> {
   117	        let mut tx = self.pool().begin().await?;
   118	        sqlx::query!("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")
   119	            .execute(&mut *tx)
   120	            .await?;
