   129	        };
   130	        let kind = row
   131	            .funder_kind
   132	            .as_deref()
   133	            .map_or(Ok(FunderKind::NotSpecified), FunderKind::from_str)
   134	            .map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?;
   135	        let aliases = sqlx::query_scalar!(
   136	            "SELECT funder_alias FROM exposed.funder_aliases WHERE funder_id = $1 ORDER BY funder_alias COLLATE \"C\"",
