   178	                    known_total: row.known_total,
   179	                    entry_count: row.entry_count,
   180	                    unknown_amount_count: row.unknown_amount_count,
   181	                })
   182	            })
   183	            .collect::<Result<Vec<_>, EntityDetailsRepoError>>()?;
