 3	use crate::domain::models::parliament_member::MemberId;
 4	use chrono::Utc;
 5	use serde::Deserialize;
 6	use serde_json::Value;
 7	
 8	use super::{ApiError, ParliamentApiClient};
 9	use crate::domain::models::declaration_ingestion::CapturedDeclaration;
10	use crate::outbound::declaration_source::decode_declaration;
11	
12	const INTERESTS_URL: &str = "https://interests-api.parliament.uk/api/v2/Interests";
13	
14	impl ParliamentApiClient {
15	    pub(super) async fn capture_declarations(
16	        &self,
17	        member: MemberId,
18	    ) -> Result<Vec<CapturedDeclaration>, ApiError> {
19	        let mut declarations = Vec::new();
20	        let mut offset = 0;
21	        loop {
22	            let url = format!(
23	                "{INTERESTS_URL}?MemberId={}&Type=Commons&ExcludeExpired=false&ExpandChildInterests=false&Skip={offset}&Take={}",
24	                member.value(),
25	                self.batch_size,
26	            );
27	            let bytes = self.client.get(url).send().await?.bytes().await?;
28	            let response: InterestPage = serde_json::from_slice(&bytes)?;
29	            if response.items.is_empty() {
30	                break;
31	            }
32	            let fetched_at = Utc::now();
33	            offset += response.items.len();
34	            for source in response.items {
35	                declarations.push(decode_declaration(source, fetched_at)?);
36	            }
37	            if offset >= response.total_results {
38	                break;
39	            }
40	        }
41	        Ok(declarations)
42	    }
43	}
